-- Madrasa Pro 1.0.8 - database schema (SQLite). Generated by tools/gen_schema_sql.py.
-- Matches app/models.py exactly (tests/test_package_layout.py). The app creates/upgrades the
-- database itself on start; this file is for inspection or a manual empty database:
--   sqlite3 "Madrasa Admin Project/data/madrasa.db" < database/schema.sql
-- PRAGMAs: foreign_keys=ON and journal_mode=WAL are set on EVERY connection (app/database.py).
-- Foreign keys (25), each with an index and an explicit ON DELETE rule:
--   class_subjects.class_id -> classes.id  ON DELETE CASCADE  indexed
--   class_subjects.subject_id -> subjects.id  ON DELETE CASCADE  indexed
--   exams.academic_year_id -> academic_years.id  ON DELETE SET NULL  indexed
--   fee_plans.class_id -> classes.id  ON DELETE CASCADE  indexed
--   sections.class_id -> classes.id  ON DELETE CASCADE  indexed
--   translations.language_code -> languages.code  ON DELETE CASCADE  indexed
--   students.class_id -> classes.id  ON DELETE RESTRICT  indexed
--   students.section_id -> sections.id  ON DELETE RESTRICT  indexed
--   attendance.student_id -> students.id  ON DELETE CASCADE  indexed
--   marks.exam_id -> exams.id  ON DELETE RESTRICT  indexed
--   marks.student_id -> students.id  ON DELETE CASCADE  indexed
--   marks.subject_id -> subjects.id  ON DELETE RESTRICT  indexed
--   payments.student_id -> students.id  ON DELETE RESTRICT  indexed
--   student_subjects.student_id -> students.id  ON DELETE CASCADE  indexed
--   student_subjects.subject_id -> subjects.id  ON DELETE CASCADE  indexed
--   users.student_id -> students.id  ON DELETE CASCADE  indexed
--   routine_slots.class_id -> classes.id  ON DELETE CASCADE  indexed
--   routine_slots.period_id -> periods.id  ON DELETE CASCADE  indexed
--   routine_slots.section_id -> sections.id  ON DELETE CASCADE  indexed
--   routine_slots.subject_id -> subjects.id  ON DELETE CASCADE  indexed
--   routine_slots.teacher_id -> users.id  ON DELETE SET NULL  indexed
--   teacher_subjects.class_id -> classes.id  ON DELETE CASCADE  indexed
--   teacher_subjects.section_id -> sections.id  ON DELETE CASCADE  indexed
--   teacher_subjects.subject_id -> subjects.id  ON DELETE CASCADE  indexed
--   teacher_subjects.teacher_id -> users.id  ON DELETE CASCADE  indexed
-- Extra indexes: attendance(date, student_id), payments(fee_month, student_id), marks(exam_id, student_id).

PRAGMA foreign_keys = ON;

-- Academic years; one is current.
CREATE TABLE IF NOT EXISTS academic_years (
    id INTEGER NOT NULL,
    name VARCHAR(32),
    is_current BOOLEAN,
    PRIMARY KEY (id)
);

-- 1.0.5: SMTP / payment gateway / SMS settings, one row per field; secrets Fernet-encrypted.
CREATE TABLE IF NOT EXISTS app_settings (
    "key" VARCHAR(80) NOT NULL,
    value TEXT,
    is_secret BOOLEAN,
    updated_at DATETIME,
    PRIMARY KEY ("key")
);

-- Classes (Grade 1-10, Hifz Level 1-10 by default).
CREATE TABLE IF NOT EXISTS classes (
    id INTEGER NOT NULL,
    name VARCHAR(64) NOT NULL,
    "order" INTEGER,
    PRIMARY KEY (id),
    UNIQUE (name)
);

-- 1.0.5: currencies (one default = fees and receipts; others for display with a rate).
CREATE TABLE IF NOT EXISTS currencies (
    id INTEGER NOT NULL,
    code VARCHAR(3) NOT NULL,
    name VARCHAR(60) NOT NULL,
    symbol VARCHAR(8) NOT NULL,
    rate FLOAT,
    decimals INTEGER,
    is_default BOOLEAN,
    is_active BOOLEAN,
    PRIMARY KEY (id),
    UNIQUE (code)
);

-- 1.0.5: interface languages (English, Bangla, Arabic RTL built in; more can be added).
CREATE TABLE IF NOT EXISTS languages (
    id INTEGER NOT NULL,
    code VARCHAR(10) NOT NULL,
    name VARCHAR(60) NOT NULL,
    native_name VARCHAR(60),
    is_rtl BOOLEAN,
    is_active BOOLEAN,
    is_default BOOLEAN,
    PRIMARY KEY (id),
    UNIQUE (code)
);

-- login_attempts
CREATE TABLE IF NOT EXISTS login_attempts (
    id INTEGER NOT NULL,
    "key" VARCHAR(200) NOT NULL,
    attempted_at DATETIME NOT NULL,
    PRIMARY KEY (id)
);
CREATE INDEX IF NOT EXISTS ix_login_attempts_attempted_at ON login_attempts (attempted_at);
CREATE INDEX IF NOT EXISTS ix_login_attempts_key ON login_attempts ("key");

-- Periods of the school day ("HH:MM"); breaks hold no class.
CREATE TABLE IF NOT EXISTS periods (
    id INTEGER NOT NULL,
    name VARCHAR(40) NOT NULL,
    start_time VARCHAR(5) NOT NULL,
    end_time VARCHAR(5) NOT NULL,
    is_break BOOLEAN,
    "order" INTEGER,
    PRIMARY KEY (id)
);

-- Numbered migrations applied by app/database.py migrate().
CREATE TABLE IF NOT EXISTS schema_migrations (
    version INTEGER NOT NULL,
    name VARCHAR(120) NOT NULL,
    applied_at DATETIME NOT NULL,
    PRIMARY KEY (version)
);

-- One row: school name, tagline, logo (validated data: URL), address, grading scale, currency.
CREATE TABLE IF NOT EXISTS school_settings (
    id INTEGER NOT NULL,
    name VARCHAR(120),
    tagline VARCHAR(160),
    logo_path VARCHAR,
    address VARCHAR(255),
    phone VARCHAR(32),
    grading_scale VARCHAR(16),
    currency VARCHAR(8),
    working_days VARCHAR(32),
    primary_color VARCHAR(7),
    secondary_color VARCHAR(7),
    landing_enabled BOOLEAN,
    default_language VARCHAR(10),
    PRIMARY KEY (id)
);

-- Subjects with max/pass marks and credits.
CREATE TABLE IF NOT EXISTS subjects (
    id INTEGER NOT NULL,
    name VARCHAR(80) NOT NULL,
    code VARCHAR(16),
    max_marks FLOAT,
    pass_marks FLOAT,
    credits FLOAT,
    is_active BOOLEAN,
    PRIMARY KEY (id),
    UNIQUE (name)
);

-- Default subjects of a class.
CREATE TABLE IF NOT EXISTS class_subjects (
    id INTEGER NOT NULL,
    class_id INTEGER NOT NULL,
    subject_id INTEGER NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uq_class_subject UNIQUE (class_id, subject_id),
    FOREIGN KEY(class_id) REFERENCES classes (id) ON DELETE CASCADE,
    FOREIGN KEY(subject_id) REFERENCES subjects (id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS ix_class_subjects_class_id ON class_subjects (class_id);
CREATE INDEX IF NOT EXISTS ix_class_subjects_subject_id ON class_subjects (subject_id);

-- Exams; published exams are visible to students.
CREATE TABLE IF NOT EXISTS exams (
    id INTEGER NOT NULL,
    name VARCHAR(80),
    academic_year_id INTEGER,
    exam_date VARCHAR(10),
    is_published BOOLEAN,
    PRIMARY KEY (id),
    FOREIGN KEY(academic_year_id) REFERENCES academic_years (id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS ix_exams_academic_year_id ON exams (academic_year_id);

-- Monthly fee per class.
CREATE TABLE IF NOT EXISTS fee_plans (
    id INTEGER NOT NULL,
    class_id INTEGER,
    fee_head VARCHAR(64),
    amount FLOAT,
    PRIMARY KEY (id),
    FOREIGN KEY(class_id) REFERENCES classes (id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS ix_fee_plans_class_id ON fee_plans (class_id);

-- Sections of a class.
CREATE TABLE IF NOT EXISTS sections (
    id INTEGER NOT NULL,
    name VARCHAR(32) NOT NULL,
    class_id INTEGER NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uq_section_class_name UNIQUE (class_id, name),
    FOREIGN KEY(class_id) REFERENCES classes (id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS ix_sections_class_id ON sections (class_id);

-- 1.0.5: the administrator's own interface texts per language (override app/locales).
CREATE TABLE IF NOT EXISTS translations (
    id INTEGER NOT NULL,
    language_code VARCHAR(10) NOT NULL,
    "key" VARCHAR(120) NOT NULL,
    text TEXT NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uq_translation_language_key UNIQUE (language_code, "key"),
    FOREIGN KEY(language_code) REFERENCES languages (code) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS ix_translations_language_code ON translations (language_code);

-- The central student record.
CREATE TABLE IF NOT EXISTS students (
    id INTEGER NOT NULL,
    student_id VARCHAR(6),
    admission_no VARCHAR(40),
    name VARCHAR(120) NOT NULL,
    dob VARCHAR(10),
    gender VARCHAR(10),
    class_id INTEGER,
    section_id INTEGER,
    roll_no INTEGER,
    admission_date VARCHAR(10),
    status VARCHAR(16),
    address VARCHAR(255),
    guardian_name VARCHAR(120),
    guardian_relation VARCHAR(32),
    guardian_phone VARCHAR(20),
    guardian_address VARCHAR(255),
    notes VARCHAR(1000),
    photo VARCHAR,
    created_at DATETIME,
    PRIMARY KEY (id),
    FOREIGN KEY(class_id) REFERENCES classes (id) ON DELETE RESTRICT,
    FOREIGN KEY(section_id) REFERENCES sections (id) ON DELETE RESTRICT
);
CREATE UNIQUE INDEX IF NOT EXISTS ix_students_admission_no ON students (admission_no);
CREATE INDEX IF NOT EXISTS ix_students_class_id ON students (class_id);
CREATE INDEX IF NOT EXISTS ix_students_section_id ON students (section_id);
CREATE UNIQUE INDEX IF NOT EXISTS ix_students_student_id ON students (student_id);

-- Daily attendance per student.
CREATE TABLE IF NOT EXISTS attendance (
    id INTEGER NOT NULL,
    student_id INTEGER,
    date VARCHAR(10),
    status VARCHAR(10),
    marked_by VARCHAR(64),
    updated_at DATETIME,
    PRIMARY KEY (id),
    FOREIGN KEY(student_id) REFERENCES students (id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS ix_attendance_date_student ON attendance (date, student_id);
CREATE INDEX IF NOT EXISTS ix_attendance_student_id ON attendance (student_id);

-- Marks per student x exam x subject.
CREATE TABLE IF NOT EXISTS marks (
    id INTEGER NOT NULL,
    student_id INTEGER,
    exam_id INTEGER,
    subject_id INTEGER,
    marks_obtained FLOAT,
    max_marks FLOAT,
    entered_by VARCHAR(64),
    updated_at DATETIME,
    PRIMARY KEY (id),
    FOREIGN KEY(student_id) REFERENCES students (id) ON DELETE CASCADE,
    FOREIGN KEY(exam_id) REFERENCES exams (id) ON DELETE RESTRICT,
    FOREIGN KEY(subject_id) REFERENCES subjects (id) ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS ix_marks_exam_id ON marks (exam_id);
CREATE INDEX IF NOT EXISTS ix_marks_exam_student ON marks (exam_id, student_id);
CREATE INDEX IF NOT EXISTS ix_marks_student_id ON marks (student_id);
CREATE INDEX IF NOT EXISTS ix_marks_subject_id ON marks (subject_id);

-- Fee payments and receipts (voided, never deleted).
CREATE TABLE IF NOT EXISTS payments (
    id INTEGER NOT NULL,
    student_id INTEGER,
    amount FLOAT,
    date VARCHAR(10),
    fee_month VARCHAR(7),
    fee_head VARCHAR(64),
    method VARCHAR(20),
    receipt_no VARCHAR(32),
    note VARCHAR(255),
    collected_by VARCHAR(64),
    is_void BOOLEAN,
    PRIMARY KEY (id),
    FOREIGN KEY(student_id) REFERENCES students (id) ON DELETE RESTRICT,
    UNIQUE (receipt_no)
);
CREATE INDEX IF NOT EXISTS ix_payments_fee_month_student ON payments (fee_month, student_id);
CREATE INDEX IF NOT EXISTS ix_payments_student_id ON payments (student_id);

-- Subjects a student takes.
CREATE TABLE IF NOT EXISTS student_subjects (
    id INTEGER NOT NULL,
    student_id INTEGER,
    subject_id INTEGER,
    is_active BOOLEAN,
    PRIMARY KEY (id),
    FOREIGN KEY(student_id) REFERENCES students (id) ON DELETE CASCADE,
    FOREIGN KEY(subject_id) REFERENCES subjects (id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS ix_student_subjects_student_id ON student_subjects (student_id);
CREATE INDEX IF NOT EXISTS ix_student_subjects_subject_id ON student_subjects (subject_id);

-- Login accounts (admin / teacher / student). password_hash = salted PBKDF2-SHA256 only.
CREATE TABLE IF NOT EXISTS users (
    id INTEGER NOT NULL,
    username VARCHAR(64) NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    role VARCHAR(16) NOT NULL,
    full_name VARCHAR(120),
    phone VARCHAR(20),
    photo VARCHAR,
    is_active BOOLEAN,
    student_id INTEGER,
    must_change_password BOOLEAN,
    created_at DATETIME,
    last_login DATETIME,
    PRIMARY KEY (id),
    UNIQUE (username),
    FOREIGN KEY(student_id) REFERENCES students (id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS ix_users_student_id ON users (student_id);

-- Weekly class routine: subject and teacher per section, day and period.
CREATE TABLE IF NOT EXISTS routine_slots (
    id INTEGER NOT NULL,
    class_id INTEGER NOT NULL,
    section_id INTEGER NOT NULL,
    day VARCHAR(3) NOT NULL,
    period_id INTEGER NOT NULL,
    subject_id INTEGER NOT NULL,
    teacher_id INTEGER,
    room VARCHAR(32),
    PRIMARY KEY (id),
    CONSTRAINT uq_routine_section_day_period UNIQUE (section_id, day, period_id),
    FOREIGN KEY(class_id) REFERENCES classes (id) ON DELETE CASCADE,
    FOREIGN KEY(section_id) REFERENCES sections (id) ON DELETE CASCADE,
    FOREIGN KEY(period_id) REFERENCES periods (id) ON DELETE CASCADE,
    FOREIGN KEY(subject_id) REFERENCES subjects (id) ON DELETE CASCADE,
    FOREIGN KEY(teacher_id) REFERENCES users (id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS ix_routine_slots_class_id ON routine_slots (class_id);
CREATE INDEX IF NOT EXISTS ix_routine_slots_period_id ON routine_slots (period_id);
CREATE INDEX IF NOT EXISTS ix_routine_slots_section_id ON routine_slots (section_id);
CREATE INDEX IF NOT EXISTS ix_routine_slots_subject_id ON routine_slots (subject_id);
CREATE INDEX IF NOT EXISTS ix_routine_slots_teacher_id ON routine_slots (teacher_id);

-- Which teacher teaches which subject in a class (section NULL = every section).
CREATE TABLE IF NOT EXISTS teacher_subjects (
    id INTEGER NOT NULL,
    teacher_id INTEGER NOT NULL,
    class_id INTEGER NOT NULL,
    section_id INTEGER,
    subject_id INTEGER NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uq_teacher_subject_slot UNIQUE (class_id, section_id, subject_id),
    FOREIGN KEY(teacher_id) REFERENCES users (id) ON DELETE CASCADE,
    FOREIGN KEY(class_id) REFERENCES classes (id) ON DELETE CASCADE,
    FOREIGN KEY(section_id) REFERENCES sections (id) ON DELETE CASCADE,
    FOREIGN KEY(subject_id) REFERENCES subjects (id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS ix_teacher_subjects_class_id ON teacher_subjects (class_id);
CREATE INDEX IF NOT EXISTS ix_teacher_subjects_section_id ON teacher_subjects (section_id);
CREATE INDEX IF NOT EXISTS ix_teacher_subjects_subject_id ON teacher_subjects (subject_id);
CREATE INDEX IF NOT EXISTS ix_teacher_subjects_teacher_id ON teacher_subjects (teacher_id);
